'use client';
import {ActionForm,VendorMediaPicker,type MediaChoice} from '@/components/vendor-forms';import {saveSellerApplication} from '@/app/vendor/actions';
type Application=Record<string,unknown>|null;type Cuisine={id:string;name:string};
export function ApplicationForm({application,cuisines,media}:{application:Application;cuisines:Cuisine[];media:MediaChoice[]}){const selected=Array.isArray(application?.cuisine_notes)?application.cuisine_notes.map(String):[];return <ActionForm action={saveSellerApplication} submitLabel="Enregistrer le brouillon" className="vendor-form application-form"><section><h2>1. Votre restaurant</h2><div className="vendor-form-grid"><label className="field full"><span>Nom du restaurant</span><input name="restaurant_name" defaultValue={String(application?.restaurant_name??'')} required/></label><label className="field full"><span>Description</span><textarea name="description" rows={4} defaultValue={String(application?.description??'')} placeholder="Décrivez simplement votre cuisine et vos spécialités."/></label><label className="field"><span>Téléphone</span><input name="phone" type="tel" defaultValue={String(application?.phone??'')} required/></label><label className="field"><span>WhatsApp <small>facultatif</small></span><input name="whatsapp" type="tel" defaultValue={String(application?.whatsapp??'')}/></label><label className="field full"><span>Email</span><input name="email" type="email" defaultValue={String(application?.email??'')}/></label></div></section><section><h2>2. Photos</h2><div className="vendor-photo-grid"><div><strong>Logo</strong><VendorMediaPicker type="logo" pathName="logo_path" initialPath={String(application?.logo_path??'')} items={media}/></div><div><strong>Photo de couverture</strong><VendorMediaPicker type="cover" pathName="cover_path" initialPath={String(application?.cover_path??'')} items={media}/></div></div></section><section><h2>3. Adresse et cuisine</h2><div className="vendor-form-grid"><label className="field full"><span>Adresse</span><input name="address" defaultValue={String(application?.address??'')}/></label><label className="field"><span>Commune / zone</span><input name="commune" defaultValue={String(application?.commune??'')}/></label><label className="field"><span>Lien Maps <small>facultatif</small></span><input name="maps_url" type="url" defaultValue={String(application?.maps_url??'')}/></label><label className="field"><span>Latitude <small>facultatif</small></span><input name="latitude" type="number" step="any" defaultValue={String(application?.latitude??'')}/></label><label className="field"><span>Longitude <small>facultatif</small></span><input name="longitude" type="number" step="any" defaultValue={String(application?.longitude??'')}/></label></div><fieldset className="cuisine-choices"><legend>Types de cuisine</legend>{cuisines.map(cuisine=><label key={cuisine.id}><input type="checkbox" name="cuisine_types" value={cuisine.name} defaultChecked={selected.includes(cuisine.name)}/><span>{cuisine.name}</span></label>)}</fieldset><div className="option-checks"><label><input type="checkbox" name="delivery_available" defaultChecked={application?.delivery_available!==false}/><span>Livraison disponible</span></label><label><input type="checkbox" name="pickup_available" defaultChecked={application?.pickup_available!==false}/><span>Retrait disponible</span></label></div></section><div className="application-actions"><button className="btn btn-outline" name="intent" value="draft">Enregistrer le brouillon</button><button className="btn btn-dark" name="intent" value="submit">Envoyer ma demande</button></div></ActionForm>}
